export const patterns=[
 ['transport',/taxi|metro|такси|метро/],['planeitem',/left.*plane|on the plane|aircraft|забрав.*самолет|самолет.*забрав/],['storage',/stor(age|e).*bag|bag.*stor|съхран/],['baggage',/bag.*(not arriv|missing)|lost baggage|багаж.*(не пристиг|изгуб|липс)/],['lost',/lost|found|изгуб|намерен/],['toilets',/toilet|restroom|тоалет/],['battery',/power.?bank|external battery|външн.*батери/],['charging',/charg.*(phone|mobile)|phone.*charg|заред|зареж/],['wifi',/wi.?fi|internet|интернет|интерн/],['liquids',/liquid|течност/],['dutyfree',/perfume|duty.?free.*(connect|taken)|парфюм/],['vat',/vat|ддс/],['pharmacy',/pharmac|аптек/],['smoking',/smok|пуш/],['prayer',/prayer|meditat|молит/],['baby',/baby|feed|chang.*baby|беб|майк|пелен/],['assistance',/wheelchair|assistance|инвалид|количк|помощ.*придвиж/],['lounge',/lounge|лаундж|салон.*бизнес/],['atm',/atm|банкомат/],['rights',/cancel|отмен/],['voucher',/voucher|ваучер|обезщет/],['passport',/passport|london|шенген|паспорт/],['exit',/leave.*airside|come back|re.?enter|напус|изляз|излиз/],['rest',/shower|rest area|layover|душ|почив/],['early',/how early|before.*gate|преди.*(полет|изход)/],['boarding',/boarding|качван/],['flight',/delay|flight.*status|закъсн|статус/],['walk',/walk.*b12|b12.*walk/],['gate',/gate|изход/],['coffee',/coffee|caf[eé]|кафене|кафе/],['water',/water|вода/],['food',/eat|food|restaurant|хран|ресторан/],['open',/open|отвор|работи/]
];
export const normalise=s=>s.toLowerCase().replace(/[—–]/g,'-').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
export function identify(q,questions){const exact=questions.find(x=>normalise(x.question)===normalise(q));if(exact)return {intent:exact.intent,id:exact.id,method:'CSV exact match'};for(const [intent,re] of patterns)if(re.test(q.toLowerCase()))return {intent,id:null,method:'Intent rule'};return {intent:null,id:null,method:'No supported match'};}
export function answer(q,{questions=[],language,scenario='normal',selectedFlight=null,pending=null,staff=true}={}){
 const lang=/[а-я]/i.test(q)?'BG':language||'EN';const bg=lang==='BG';
 const explicitFlight=q.match(/\bDEMO\s*\d+\b/i); const matchedFlight=explicitFlight?flights.find(f=>f.number===explicitFlight[0].replace(/\s/g,'').toUpperCase()):null;
 let hit=identify(q,questions);if(!hit.intent&&matchedFlight)hit={intent:pending||'flight',id:null,method:'Flight follow-up'};if(!hit.intent&&pending==='gate'&&/^\s*[abcd]\s*\d{1,2}\s*$/i.test(q))hit={intent:'gate',id:null,method:'Gate follow-up'};
 if(/ignore.*(instruction|rule)|system prompt|jailbreak|игнорирай|reveal.*prompt/i.test(q))return {lang,intent:'guardrail',text:bg?'Мога да помогна с пътнически въпроси за Терминал 2. Не предоставям вътрешни инструкции или достъп до системи.':'I can help with Terminal 2 passenger questions. I cannot disclose internal instructions or provide system access.',source:'service',route:'Boundary',method:'Guardrail'};
 if(!hit.intent)return {lang,intent:'unknown',text:bg?'Не намирам надежден отговор в този прототип. Мога да помогна с полети, изходи, услуги и правила за пътуване. Можете да подготвите предаване към информационното гише.':'I couldn’t find a reliable answer in this prototype. Try flights, gates, facilities or travel guidance, or prepare a handover to the information desk.',source:'service',route:'Fallback',team:'Information desk',method:hit.method,staff};
 const record=knowledge[hit.intent];const result={...hit,lang,text:record[bg?'bg':'en'],source:record.source,team:record.team,route:record.team?'Handover suggested':'Knowledge answer',staff};
 const dynamic=['flight','boarding','gate'].includes(hit.intent);const f=matchedFlight||selectedFlight;
 if(dynamic&&explicitFlight&&!matchedFlight){result.text=bg?'Този полет не е в примерния набор. Налични са DEMO101, DEMO202 и DEMO303. За реален полет проверете таблата или се обърнете към авиокомпанията.':'That flight is not in the demo dataset. Available flights are DEMO101, DEMO202 and DEMO303. Check airport displays or your airline for real flights.';result.route='Flight unavailable';return result;}
 if(scenario==='stale'&&(dynamic||['terminal','commercial'].includes(record.source))){result.text=bg?'Източникът е с изтекла валидност. Няма да използвам стари данни за изходи, часове или маршрути. Проверете таблата или се обърнете към информационното гише.':'The source has expired. I won’t use stale gate, opening-hour or route data. Check airport displays or ask the information desk for the current information.';result.route='Stale source blocked';result.team='Information desk';return result;}
 if(scenario==='fog'&&['flight','boarding','gate','walk','open','coffee','food','water','passport'].includes(hit.intent)){result.text=bg?'Демонстрационно известие N-004, 02:00: гъста мъгла нарушава полетите. Изходите и часовете на качване не са потвърдени; примерните обекти за храна са затворени. Проверявайте таблата и авиокомпанията. Не се придвижвайте към непотвърден изход. Дежурният мениджър е маршрутът за съдействие в този сценарий.':'Simulated duty notice N-004, 02:00: fog is disrupting flights. Gates and boarding times are unconfirmed; the demo food outlets are closed. Check airport displays and your airline. Do not walk to an unconfirmed gate. The duty manager is the assistance route for this scenario.';result.source='notice';result.route='Urgent notice override';result.team='Duty manager';return result;}
 if(dynamic){
 const gate=q.match(/\b([abcd])\s*(\d{1,2})\b/i);if(hit.intent==='gate'&&gate){let g=(gate[1]+gate[2]).toUpperCase();let route={B12:['B','8–10'],A6:['A','5–7'],B7:['B','6–8']}[g];if(!route){result.text=bg?`Нямам проверен маршрут до ${g}. Не мога да потвърдя дали изходът съществува в тази зона. Проверете бордната карта и таблата; информационното гише може да помогне.`:`I have no validated route to ${g} and cannot confirm it is in this area. Check your boarding pass and the displays; the information desk can help.`;result.team='Information desk';result.route='Unverified route';}else{result.text=bg?`Примерен маршрут до ${g}: от проверката следвайте табелите към ${route[0]}, после ${g}. Около ${route[1]} минути без опашки или паспортна проверка. Това е демонстрационна, не реална навигация.`:`Demo route to ${g}: from security, follow ${route[0]} signs, then ${g}. Allow about ${route[1]} minutes, excluding queues or passport control. This is illustrative, not real airport navigation.`;}return result;}
 if(!f){result.route='Clarification';result.pending=hit.intent;result.pickFlight=true;return result;}
 result.source='flight';result.route='Simulated flight query';result.flight=f;
 result.text=bg?`${f.number} до ${f.bg}: примерен изход ${f.gate}, качване ${f.boarding}, планирано излитане ${f.departure}. ${f.status==='Delayed'?`Закъснение; очаквано излитане ${f.estimate}.`:'По разписание.'} Около ${f.walk} минути пеша от проверката. Това са измислени данни; за реално пътуване проверете таблата.`:`${f.number} to ${f.city}: demo gate ${f.gate}, boarding ${f.boarding}, scheduled departure ${f.departure}. ${f.status==='Delayed'?`Delayed; estimated departure ${f.estimate}.`:'On time.'} About ${f.walk} minutes from security. All values are fictional; check airport displays for real travel.`;
 }
 return result;
}
